PCV4_BLOCK = 'PCV4:()=>head("PCV.4 — INTERVENTION VALUE","What Should We Do — The Value of Acting Now","PCV.4")+`\n<div class="info">Compare intervention cost against the expected cost of doing nothing.</div>\n<div class="kpis">\n ${kpi("INTERVENTION COST (IC)","R3.20m","To implement","good")}\n ${kpi("AVOIDED CONSEQUENCE (AC)","R23.70m","Cost avoided","bad")}\n ${kpi("NET INTERVENTION VALUE","R20.50m","NIV = AC − IC","good")}\n ${kpi("NIV RATIO","7.41x","Value multiple","good")}\n ${kpi("CONFIDENCE","72%","In NIV estimate","warn")}\n ${kpi("DECISION","INTERVENE","High value opportunity","good")}\n</div>\n<div class="grid3" style="margin-top:12px">\n ${card("FORMULAS",`<p><b>NIV = AC − IC</b></p><p>NIV Ratio = AC / IC</p><p>Expected NIV = (AC × Confidence) − IC</p>`)}\n ${card("INTERVENTION COMPONENTS",`\n  <table class="table">\n  <tr><th>Component</th><th>R\'m</th></tr>\n  <tr><td>Direct Implementation</td><td>2.10</td></tr>\n  <tr><td>Execution & Support</td><td>0.70</td></tr>\n  <tr><td>Contingency 15%</td><td>0.40</td></tr>\n  <tr><td><b>TOTAL IC</b></td><td><b>3.20</b></td></tr>\n  <tr><td>Schedule Delay Cost avoided</td><td>9.80</td></tr>\n  <tr><td>Additional Drilling avoided</td><td>6.50</td></tr>\n  <tr><td>Equipment Downtime avoided</td><td>4.40</td></tr>\n  <tr><td>Other Indirect avoided</td><td>3.00</td></tr>\n  <tr><td><b>TOTAL AC</b></td><td><b>23.70</b></td></tr></table>\n `)}\n ${card("NIV SUMMARY",`\n  <table class="table">\n  <tr><td>NIV</td><td>R20.50m</td></tr>\n  <tr><td>NIV Ratio</td><td>7.41x</td></tr>\n  <tr><td>Decision Threshold</td><td>1.50x</td></tr>\n  <tr><td>Rule</td><td>Intervene if Ratio ≥ 1.5x and Confidence ≥ 50%</td></tr></table>\n `)}\n</div>\n<div class="grid2" style="margin-top:12px">\n ${card("RECOMMENDED INTERVENTION",`\n  <p><b>INT-EXPL-001</b> · Ground Condition Management</p>\n  <p>Targeted ground support & drilling optimisation · Geotechnical Team · Start 25 Aug 2026 · 10 days</p>\n  <p><span class="badge green">Recommended</span></p>\n  <p>Expected: −14 days downtime · +16% advance · lower failure risk</p>\n `)}\n ${card("EXPECTED VALUE",`\n  <table class="table">\n  <tr><td>AC</td><td>R23.70m</td></tr>\n  <tr><td>Confidence</td><td>72%</td></tr>\n  <tr><td>Probability-Weighted AC</td><td>R17.06m</td></tr>\n  <tr><td>IC</td><td>R3.20m</td></tr>\n  <tr><td><b>EXPECTED NIV</b></td><td class="good"><b>R13.86m</b></td></tr>\n  <tr><td><b>EXPECTED RATIO</b></td><td class="good"><b>5.33x</b></td></tr></table>\n `)}\n</div>\n<div class="actionrow" style="margin-top:12px">${button("Back to Analytics W1–W10","W1","green")}</div>\n<p class="side-note" style="margin-top:10px">PCV.4 converts insight into decision by quantifying the value of action.</p>\n`,'


p = Path('index.html')
t = p.read_text(encoding='utf-8', errors='replace').replace('\r\n', '\n')

# Close widgetViews
m = '\nconst pcvViews={'
i = t.find(m)
if i < 0:
    raise SystemExit('const pcvViews={ not found')
head = t[:i].rstrip()
if not head.endswith('};'):
    if head.endswith(','):
        head = head[:-1]
    t = head + '\n};\nconst pcvViews={' + t[i + len(m):]
    print('FIXED: closed widgetViews')
else:
    print('widgetViews already closed')

# F08
if re.search(r'F08:\(\)=>', t):
    t2, n = re.subn(r'F08:\(\)=>[\s\S]*?(?=(?:\n(?:W\d+|PCV\d+|L\d|function |const )|\n\}\s*;))', F08_BLOCK, t, count=1)
    if n != 1:
        t2, n = re.subn(r'F08:\(\)=>[\s\S]*?(?=,\s*\n(?:[A-Z0-9]+):|\n\}\s*;)', F08_BLOCK, t, count=1)
    if n == 1:
        t = t2
        print('F08 replaced')
    else:
        t = t.replace('const widgetViews={', F08_BLOCK + '\nconst widgetViews={', 1)
        print('F08 injected')
else:
    t = t.replace('const widgetViews={', F08_BLOCK + '\nconst widgetViews={', 1)
    print('F08 injected')

for key, block in [('PCV1', PCV1_BLOCK), ('PCV2', PCV2_BLOCK), ('PCV3', PCV3_BLOCK), ('PCV4', PCV4_BLOCK)]:
    pattern = rf'{key}:\(\)=>[\s\S]*?(?=(?:\nPCV\d:)|(?:\n\}}))'
    t2, n = re.subn(pattern, block, t, count=1)
    if n != 1:
        raise SystemExit(f'{key} replace failed matches={n}')
    t = t2
    print(f'{key} installed')

if 'function l3View' not in t:
    raise SystemExit('Safety: l3View missing')
if 'INTERVENTION VALUE' not in t and 'NIV = AC' not in t:
    raise SystemExit('Safety: PCV4 missing')
if 'SPECIALIST INTELLIGENCE' not in t:
    raise SystemExit('Safety: F08 missing')

p.write_text(t, encoding='utf-8', newline='\n')
print('DONE: fix + F08 + PCV1-4 installed')
